		return op.NewValue
	case OpUpdateAttr:
		if op.NewValue != nil {
			return op.NewValue
		}
		return op.OldValue
	case OpRemove:
		return op.OldValue
	default:
		return nil
	}
}

// opBaseValue returns the value present in the base document for an
// operation's path.
func opBaseValue(op DiffOperation) interface{} {
	switch op.Type {
	case OpAdd:
		return nil
	default:
		return op.OldValue
	}
}

// Convenience method: applies a patch document to the receiver.
'''
s = s[:old_opval] + new_opval + s[old_opval_end:]

